import requests
from yt_dlp.extractor.common import traverse_obj
from yt_dlp.extractor.youtube import YoutubeTabIE
from yt_dlp import YoutubeDL
import json
downloader = YoutubeDL()
ie = YoutubeTabIE(downloader)
url = 'https://music.youtube.com/watch?v=e3OBPOKtMgA'
id = 'e3OBPOKtMgA' #ie._match_id(url)

data = {
    'videoId': id,
#    "context": {
#        "client": {
#            "userAgent": "Mozilla/5.0 (X11; Linux x86_64; rv:154.0) Gecko/20100101 Firefox/154.0,gzip(gfe)",
#            "clientName": "WEB_REMIX",
#            "clientVersion": "1.20260830.16.00"
#        }
#    }
}

mdata = requests.post('https://music.youtube.com/youtubei/v1/next?prettyPrint=false', json=data).json()
#print(r.text)
mdata = ie._extract_response(id, data, ep = 'next', api_hostname='music.youtube.com', default_client='web_music')
#mdata = ie._download_json("https://music.youtube.com/youtubei/v1/next?prettyPrint=false", id, data=json.dumps(data).encode())
menu = traverse_obj(mdata, ('contents', 'singleColumnMusicWatchNextResultsRenderer', 'tabbedRenderer', 'watchNextTabbedResultsRenderer', 'tabs', 0, 'tabRenderer', 'content', 'musicQueueRenderer', 'content', 'playlistPanelRenderer', 'contents', 0, 'playlistPanelVideoRenderer', 'menu', 'menuRenderer', 'items', ..., ...))
if not menu:
    raise

right = ['Go to album', 'View song credits']
left = ['ALBUM', 'PEOPLE_GROUP']
filtered = {}
for i in menu:
    text = ''.join(traverse_obj(i, ('text', 'runs', ..., 'text')))
    icon = traverse_obj(i, ('icon', 'iconType'))
    _type = traverse_obj(i, ('navigationEndpoint', 'browseEndpoint', 'browseEndpointContextSupportedConfigs', 'browseEndpointContextMusicConfig', 'pageType'))
    right_match = text in right
    left_match = icon in left
    full_match = (text, icon) in list(zip(right, left))
    if left_match and right_match and not full_match:
        raise
    if left_match or right_match:
        ie.report_warning('one fallback failed')
    if full_match or left_match or right_match:
        filtered[icon] = ie._extract_response(id, traverse_obj(i, ('navigationEndpoint', 'browseEndpoint')), ep = 'browse', api_hostname='music.youtube.com', default_client='web_music')

album = filtered['ALBUM']

album = traverse_obj(album, ('contents', 'twoColumnBrowseResultsRenderer', 'tabs', 0, 'tabRenderer', 'content', 'sectionListRenderer', 'contents', 0, 'musicResponsiveHeaderRenderer'))
album_title = ''.join(traverse_obj(album, ('title', 'runs', ..., 'text')))
album_type = traverse_obj(album, ('subtitle', 'runs', ..., 'text'))[0]
album_artists = list(filter(lambda x: x is not None, map(lambda x: x.get('text') if 'navigationEndpoint' in x else None, traverse_obj(album, ('straplineTextOne', 'runs', ...)))))

filtered['ALBUM'] = {
    'album_title': album_title,
    'album_type': album_type,
    'album_artists': album_artists,
}

author_ = filtered['PEOPLE_GROUP']
author_data = {
    ''.join(traverse_obj(
        i,
        ('title', 'runs', ..., 'text'),
    )): traverse_obj(
        i,
        ('subtitle', 'runs', ..., 'text'),
    )[::2]
    for i in traverse_obj(author_, ('onResponseReceivedActions', 0, 'openPopupAction', 'popup', 'dismissableDialogRenderer', 'sections', ..., 'dismissableDialogContentSectionRenderer'))
}

filtered['PEOPLE_GROUP'] = author_data

with open('tmp.json', 'w') as f:
    json.dump(filtered, f, indent=4)
